using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using CheapLoc;
using Dalamud.Plugin;
using Dalamud.Plugin.Services;

namespace NekoDex;

/// <summary>
/// All user-visible text goes through <see cref="Get"/> so it can be localised. Keys are stable identifiers; the fallback is the English text.
/// Translations live in loc/{language}.json next to the plugin (CheapLoc format, generated by tools/LocExport); missing keys fall back to English.
/// The language is Dalamud's UI language unless the configuration overrides it, which is how languages Dalamud lacks (Swedish) are selected.
/// </summary>
internal static class Strings
{
    public const string English = "en";

    public static string Get(string key, string fallback) => Loc.Localize(key, fallback);

    /// <summary>Resolves and loads the language for the current configuration.</summary>
    public static void Apply(IDalamudPluginInterface pluginInterface, Configuration config, IPluginLog log)
        => Load(config.LanguageOverride ?? pluginInterface.UiLanguage, pluginInterface, log);

    /// <summary>Language codes with a usable translation file next to the plugin, English first.</summary>
    public static IReadOnlyList<string> Available(IDalamudPluginInterface pluginInterface)
    {
        var list = new List<string> { English };
        var dir = LocDirectory(pluginInterface);
        if (dir is not null && Directory.Exists(dir))
        {
            foreach (var file in Directory.EnumerateFiles(dir, "*.json").OrderBy(f => f, StringComparer.OrdinalIgnoreCase))
            {
                var code = Path.GetFileNameWithoutExtension(file);
                if (code != English && IsUsable(file))
                {
                    list.Add(code);
                }
            }
        }

        return list;
    }

    public static string DisplayName(string code) => code switch
    {
        "en" => "English",
        "sv" => "Svenska",
        "de" => "Deutsch",
        "fr" => "Français",
        "ja" => "日本語",
        _ => code,
    };

    private static void Load(string language, IDalamudPluginInterface pluginInterface, IPluginLog log)
    {
        var assembly = typeof(Strings).Assembly;
        var dir = LocDirectory(pluginInterface);
        var file = dir is null || string.IsNullOrEmpty(language) ? null : Path.Combine(dir, language + ".json");

        if (language != English && file is not null && IsUsable(file))
        {
            try
            {
                Loc.Setup(File.ReadAllText(file), assembly);
                log.Information("Loaded {Language} strings from {File}", language, file);
                return;
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                log.Warning(ex, "Could not read {File}; using English", file);
            }
        }

        Loc.SetupWithFallbacks(assembly);
    }

    private static string? LocDirectory(IDalamudPluginInterface pluginInterface)
    {
        var directory = pluginInterface.AssemblyLocation.Directory?.FullName;
        return directory is null ? null : Path.Combine(directory, "loc");
    }

    /// <summary>An empty template ("{}") does not count as a translation.</summary>
    private static bool IsUsable(string file)
    {
        try
        {
            return File.Exists(file) && new FileInfo(file).Length > 4;
        }
        catch (IOException)
        {
            return false;
        }
    }
}
